WITH with_windows AS (SELECT id, session_id, event_type, page, event_time, duration_sec, LAST_VALUE(duration_sec, TRUE) OVER (PARTITION BY session_id ORDER BY event_time ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_duration_sec, SUM(duration_sec) OVER (ORDER BY event_time ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_duration_sec FROM web_events) SELECT session_id, SORT_ARRAY(COLLECT_SET(page)) AS page_list, COUNT(*) FILTER (WHERE event_type = 'add_to_cart') AS add_to_cart_rows, PERCENTILE_APPROX(duration_sec, 0.5) AS duration_sec_p50, SORT_ARRAY(COLLECT_SET(page)) AS page_list_2, MIN(event_time) AS first_seen, SUM(CASE WHEN page = '/cart' THEN last_known_duration_sec ELSE 0 END) AS cart_last_known_duration_sec FROM with_windows GROUP BY session_id HAVING cart_last_known_duration_sec < 0;
